/**
 * @fileoverview A package the `ext.b` module imports to run source it is given (#717): it writes the source to a file
 * beside itself, named by the source's hash, and imports that file. The files are git-ignored.
 * @module api_tests/api_test_host_record_leaf/node_modules/write-pkg
 */

import fs from "node:fs";
import crypto from "node:crypto";

/**
 * Write module source to a file beside this one and import it.
 * @param {string} source - The module source.
 * @returns {Promise<object>} Its namespace.
 * @example
 * await run("export const x = 1;");
 */
export function run(source) {
	const dir = new URL("./generated/", import.meta.url);
	fs.mkdirSync(dir, { recursive: true });
	const file = new URL(`${crypto.createHash("sha256").update(source).digest("hex").slice(0, 16)}.mjs`, dir);
	// Written aside and renamed into place, so a process importing it at the same time never reads a partial file.
	const temp = new URL(`${file.pathname.split("/").pop()}.${process.pid}.tmp`, dir);
	fs.writeFileSync(temp, source);
	fs.renameSync(temp, file);
	return import(file.href);
}
